styles.css:
position: relative;
overflow: hidden;
--ls-card-case-study-border-active: var(--wp--custom--color--link--accent);
--ls-card-case-study-shadow-active: var(--wp--custom--shadow--card--hover);
--ls-card-case-study-lift: var(--wp--custom--animation--lift--md);

& .ls-card-case-study__link::before {
	content: "";
	position: absolute;
	inset: 0;
}

& .ls-card-case-study__link:focus-visible {
	outline: 2px solid var(--wp--custom--color--focus--ring);
	outline-offset: 2px;
}

& a:not(.ls-card-case-study__link) {
	position: relative;
	z-index: 1;
}
